// 00A247E0  R_CheckDvarModified  (gfx_d3d/r_dvars.cpp:2134)

bool __cdecl R_CheckDvarModified(dvar_t *dvar)

{
  bool bVar1;
  
  bVar1 = Dvar_GetModified(dvar);
  if (!bVar1) {
    return false;
  }
  Dvar_ClearModified(dvar);
  return true;
}


// 00A24810  R_GetDefaultNearClip  (gfx_d3d/r_dvars.cpp:2143)

float __cdecl R_GetDefaultNearClip(void)

{
  float fVar1;
  float fVar2;
  
  fVar2 = Dvar_GetFloat(r_znear);
  fVar1 = fVar2;
  if (0.0 <= fVar2 - 4.0) {
    fVar1 = 4.0;
  }
  if (1.0 - fVar2 < 0.0) {
    return fVar1;
  }
  return 1.0;
}


// 00A24880  R_GetDefaultNearClip_DepthHack  (gfx_d3d/r_dvars.cpp:2152)

float __cdecl R_GetDefaultNearClip_DepthHack(void)

{
  float fVar1;
  
  fVar1 = Dvar_GetFloat(r_znear_depthhack);
  if (0.0 <= 0.1 - fVar1) {
    return 0.1;
  }
  return fVar1;
}


// 00A248D0  DvarBlock_SetFog  (gfx_d3d/r_dvars.cpp:2229)

void __cdecl DvarBlock_SetFog(void)

{
  if (gDvarDataReady == DBLOCK_READY_FOG) {
    Dvar_SetFloat(r_fogBaseDist,dvar_buffer[0]);
    Dvar_SetFloat(r_fogHalfDist,dvar_buffer[1]);
    Dvar_SetFloat(r_fogBaseHeight,dvar_buffer[2]);
    Dvar_SetFloat(r_fogHalfHeight,dvar_buffer[3]);
    Dvar_SetVec3(r_fogColor,dvar_buffer[4],dvar_buffer[5],dvar_buffer[6]);
    Dvar_SetFloat(r_fogOpacity,dvar_buffer[7]);
    Dvar_SetVec3(r_fogSunColor,dvar_buffer[8],dvar_buffer[9],dvar_buffer[10]);
    Dvar_SetFloat(r_fogSunOpacity,dvar_buffer[0xb]);
    Dvar_SetFloat(r_fogSunPitch,dvar_buffer[0xc]);
    Dvar_SetFloat(r_fogSunYaw,dvar_buffer[0xd]);
    Dvar_SetFloat(r_fogSunInner,dvar_buffer[0xe]);
    Dvar_SetFloat(r_fogSunOuter,dvar_buffer[0xf]);
    gDvarDataReady = DBLOCK_EMPTY;
  }
  return;
}


